 function chart(rows){const hours=Array.from({length:24},(_,hour)=>({...plus(rows.filter(r=>Number(r.hour)===hour)),hour})),max=Math.max(1,...hours.map(r=>r.all_count)),w=700,h=155;let svg='<svg class="live-chart" viewBox="0 0 760 210" role="img" aria-label="当地创建小时全部与成功笔数">';for(let i=0;i<4;i++){const y=15+i*h/3;svg+='<line x1="43" x2="742" y1="'+y+'" y2="'+y+'"/><text x="34" y="'+(y+3)+'" text-anchor="end">'+C(Math.round(max*(3-i)/3))+'</text>'}for(const [key,color]of[['all_count','#4e75ed'],['success_count','#35a697']])svg+='<polyline fill="none" stroke="'+color+'" stroke-width="2.4" points="'+hours.map((r,i)=>(43+i*w/23)+','+(15+h-r[key]/max*h)).join(' ')+'"/>';for(let i=0;i<24;i+=3)svg+='<text x="'+(43+i*w/23)+'" y="193" text-anchor="middle">'+String(i).padStart(2,'0')+':00</text>';return svg+'</svg><div class="live-legend"><span>● 全部笔数</span><span style="color:#35a697">● 成功笔数</span><span>全部 / 处理中按各平台当地创建小时；成功按各平台当地成功小时</span></div>'}
