 window.liveOrder=function(index){const r=L.detail?.rows?.[index];if(!r)return;const p=L.detail.platform,zone=p?.timezone;openDrawer('订单详情 · '+(r.order_number||r.order_no||''),box('订单与关联字段',table(['字段','值'],[['订单号',E(r.order_number||r.order_no||'—')],['系统 ID',E(r.system_order_id||r.id||'—')],['三方订单号',E(r.third_party_order_number||r.provider_order_number||'—')],['会员 ID',E(r.member_id||'—')],['UTR',E(r.utr||'未提供')],['平台',E(p?.name)],['团队',E(p?.team||'未绑定团队')],['国家',E(p?.country)],['包网系统',E(p?.source)],['三方',E(r.provider)],['原始三方',E(r.raw_provider===undefined?'接口未提供':r.raw_provider==null||r.raw_provider===''?'（空）':r.raw_provider)],['原始类型',E(r.channel_type||'—')],['归类依据',E(providerOrders.reason(r))],['方向',directionName(r.direction)],['订单金额',N(r.amount)],['实际金额',N(r.actual_amount)],['订单状态',E(statName(r.status_group||r.status))]]))+box('提交与成功时间',table(['创建时间','成功时间','数据同步时间','时区'],[[E(formatTime(r.created_at,zone)),E(formatTime(r.success_at,zone)),E(formatTime(r.synced_at,zone)),E(zone)]]))+box('费用与费率依据',table(['估算手续费','实际手续费','费率版本','费率生效时间'],[['—',N(r.withdraw_fee),'—','—']]),'当前源数据未提供历史费率匹配结果；不将空值当作零费用'))};

 window.liveRates=async function(force=false,reset=false){if(L.feeView!=='normalized'&&window.HensemLiveRatesRestored){render();if(force||!HensemLiveRatesRestored.snapshot().hasGrid)await HensemLiveRatesRestored.load();return}if(L.fees&&!force){render();return}if(reset)L.feePage=1;const serial=++L.feeSerial;L.feeLoading=true;L.feeError='';L.dirty=false;render();try{const request={action:'rates',scopeType:L.feeScope,offset:(L.feePage-1)*L.feeSize,limit:L.feeSize};if(L.feeCountry!=='all')request.country=L.feeCountry;if(L.feeQuery)request.query=L.feeQuery;const result=await window.hensemLiveRequest(request);if(serial!==L.feeSerial)return;const max=Math.max(1,Math.ceil(Number(result.total||0)/L.feeSize));if(L.feePage>max){L.feePage=max;L.feeLoading=false;return liveRates(true)}L.fees=result;}catch(e){if(serial!==L.feeSerial)return;L.feeError=e.message}finally{if(serial===L.feeSerial){L.feeLoading=false;state.page==='rates'&&render()}}};
 window.liveExport=function(){if(isSupervisorPage(state.page)){toast('员工测试站尚未接通，暂无可导出记录');return}const page=document.getElementById('page'),tables=[...page.querySelectorAll('table')];if(!tables.length){toast('当前没有可导出的表格');return}const rows=tables.flatMap(t=>[...t.querySelectorAll(':scope > thead > tr, :scope > tbody > tr:not(.provider-expanded-row), :scope > tfoot > tr')].map(tr=>[...tr.cells].map(td=>td.innerText)));const quote=v=>'"'+String(/^[=+@\-\t\r]/.test(v)?"'"+v:v).replace(/"/g,'""')+'"',url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Hensem-当前页-'+state.page+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前可见表格页')};
  let initialLoad=null,initialDataDeferred=false;
  function initializeLiveData(){if(initialLoad)return initialLoad;initialLoad=(async()=>{try{const r=await (L.catalogReady?{platforms:L.catalog,withdrawPlatforms:L.withdrawCatalog}:window.hensemLiveRequest({action:'catalog'}));L.catalog=r.platforms||[];L.withdrawCatalog=r.withdrawPlatforms||[];L.catalogReady=true;if(!isSupervisorPage(state.page)&&state.page!=='overview'&&!((isFlowPage(state.page)||providerDirection(state.page)||state.page==='provider_daily')&&L.catalog.length))reportData?.loadCatalog().then(list=>{if(!L.country&&list?.length){L.country=list.find(p=>p.country)?.country||'';livePeriod('yesterday',false);if(reportPages.has(state.page))liveLoad(false)}});const initialCatalog=visibleCatalog(),preferred=initialCatalog.find(p=>String(p.name||'').toUpperCase()==='91CLUB')||initialCatalog[0]||{};L.country=preferred.country||initialCatalog.find(p=>p.country)?.country||'';L.platform='all';L.source='all';L.multi={team:[],platform:[],source:[],provider:[],direction:L.direction==='all'?[]:[L.direction]};syncCurrency();L.providerConfigCountry=L.country;livePeriod('yesterday',false);if(isSupervisorPage(state.page)){initialDataDeferred=true;render();return}initialDataDeferred=false;if(state.page==='overview'){L.overviewQueried=false;L.dirty=true;render();return;}if(state.page!=='collected_data')loadProviderOptions();if(state.page==='collected_data')await collectedPage.load();else if(state.page==='rates')await liveRates();else if(state.page==='provider_config')await providerConfigLoad();else if(state.page==='teams'||state.page==='platform_systems')await platformAssignmentsLoad();else if(state.page==='workorders')await workordersLoad();else if(state.page==='payout_config')await HensemLivePayoutConfig.ensureLoaded();else if(isWithdrawPage(state.page))await autoWithdrawLoad();else if(state.page==='deposit_tracking')await depositIssuesLoad();else if(!gaps[state.page])await liveLoad();else render();}catch(e){L.error=e.message;render()}finally{initialLoad=null;L.initialReadComplete=true;window.liveHeader?.()}})();return initialLoad;}
  if(isSupervisorPage(state.page))render();else initializeLiveData();
